/**
 * 剪贴板隐私保护：识别系统级忽略格式标记与常见密码管理器进程
 *
 * 1. Windows 官方剪贴板历史规范格式：
 *    - ExcludeClipboardContentFromMonitorProcessing
 *    - CanIncludeInClipboardHistory（值为 0 表示禁止入库）
 *    - Clipboard Viewer Ignore（传统密码管理器通用标记）
 * 2. macOS NSPasteboard 隐私标记（ConcealedType / TransientType / AutoGeneratedType）
 * 3. 常见密码管理器前景进程黑名单兜底
 */
import { clipboard } from "electron";
import { getForegroundProcessName } from "./foreground-window";

/** 出现即直接忽略的剪贴板格式名（小写匹配） */
const ALWAYS_IGNORE_FORMATS = new Set([
  "excludeclipboardcontentfrommonitorprocessing",
  "clipboard viewer ignore",
  "org.nspasteboard.concealedtype",
  "org.nspasteboard.transienttype",
  "org.nspasteboard.autogeneratedtype",
  "com.agilebits.onepassword",
]);

const CAN_INCLUDE_FORMAT = "canincludeinclipboardhistory";

/** 常见密码管理器与系统凭据弹窗进程（小写） */
export const SENSITIVE_PROCESS_NAMES = new Set([
  "keepass.exe",
  "keepassxc.exe",
  "bitwarden.exe",
  "1password.exe",
  "enpass.exe",
  "lastpass.exe",
  "dashlane.exe",
  "roboform.exe",
  "nordpass.exe",
  "protonpass.exe",
  "credentialuibroker.exe",
]);

export type ClipboardPrivacyInput = {
  formats: string[];
  readBuffer: (format: string) => Buffer;
  foregroundProcessName: string | null;
};

function isZeroFlagBuffer(buf: Buffer | null | undefined): boolean {
  if (!buf || buf.length === 0) return false;
  if (buf.length >= 4) {
    return buf.readUInt32LE(0) === 0;
  }
  return buf[0] === 0;
}

/** 纯逻辑判断当前剪贴板是否应跳过入库（便于单元测试） */
export function shouldIgnoreClipboardCapture(input: ClipboardPrivacyInput): boolean {
  for (const format of input.formats) {
    const lower = format.trim().toLowerCase();
    if (ALWAYS_IGNORE_FORMATS.has(lower)) {
      return true;
    }
    if (lower === CAN_INCLUDE_FORMAT) {
      try {
        const buf = input.readBuffer(format);
        if (isZeroFlagBuffer(buf)) {
          return true;
        }
      } catch {
        // 读取失败时不误杀普通记录
      }
    }
  }

  if (input.foregroundProcessName) {
    const normalized = input.foregroundProcessName.trim().toLowerCase();
    if (SENSITIVE_PROCESS_NAMES.has(normalized)) {
      return true;
    }
  }

  return false;
}

/** 检查当前系统剪贴板是否为敏感/受保护内容 */
export function isSensitiveClipboardContent(): boolean {
  try {
    const formats = clipboard.availableFormats();
    return shouldIgnoreClipboardCapture({
      formats,
      readBuffer: (format) => clipboard.readBuffer(format),
      foregroundProcessName: getForegroundProcessName(),
    });
  } catch {
    return false;
  }
}
